import Foundation
import AVFoundation
import XCTest

final class GeometryTests:XCTestCase {
 let size=CGSize(width:640,height:480)
 func testIdentityKeepsSizeAndTransform() throws {let g=try XCTUnwrap(EditedAvatarVideoGeometry(naturalSize:size,transform:.identity));XCTAssertEqual(g.size,size);XCTAssertEqual(g.transform,.identity)}
 func testPortraitRotationUsesBoundingRectangle() throws {let g=try XCTUnwrap(EditedAvatarVideoGeometry(naturalSize:size,transform:CGAffineTransform(a:0,b:1,c:-1,d:0,tx:480,ty:0)));XCTAssertEqual(g.size,CGSize(width:480,height:640));XCTAssertEqual(CGPoint(x:0,y:0).applying(g.transform),CGPoint(x:480,y:0))}
 func testNegativeTranslatedBoundsAreNormalized() throws {let g=try XCTUnwrap(EditedAvatarVideoGeometry(naturalSize:size,transform:CGAffineTransform(a:0,b:1,c:-1,d:0,tx:-30,ty:-40)));XCTAssertEqual(g.size,CGSize(width:480,height:640));XCTAssertEqual(CGRect(origin:.zero,size:size).applying(g.transform),CGRect(x:0,y:0,width:480,height:640))}
 func testHorizontalMirrorIsPreserved() throws {let g=try XCTUnwrap(EditedAvatarVideoGeometry(naturalSize:size,transform:CGAffineTransform(a:-1,b:0,c:0,d:1,tx:640,ty:0)));XCTAssertEqual(CGPoint(x:10,y:20).applying(g.transform),CGPoint(x:630,y:20))}
 func testVerticalMirrorIsPreserved() throws {let g=try XCTUnwrap(EditedAvatarVideoGeometry(naturalSize:size,transform:CGAffineTransform(a:1,b:0,c:0,d:-1,tx:0,ty:480)));XCTAssertEqual(CGPoint(x:10,y:20).applying(g.transform),CGPoint(x:10,y:460))}
 func testShearedBoundsDoNotUseSizeVectorCancellation() throws {let g=try XCTUnwrap(EditedAvatarVideoGeometry(naturalSize:size,transform:CGAffineTransform(a:1,b:0,c:-1,d:1,tx:0,ty:0)));XCTAssertEqual(g.size,CGSize(width:1120,height:480));XCTAssertEqual(CGRect(origin:.zero,size:size).applying(g.transform),CGRect(origin:.zero,size:g.size))}
 func testNonFiniteAndSingularTransformsAreRejected() {for t in [CGAffineTransform(a:0,b:0,c:0,d:0,tx:0,ty:0),CGAffineTransform(a:1,b:1,c:1,d:1,tx:0,ty:0),CGAffineTransform(a:CGFloat.nan,b:0,c:0,d:1,tx:0,ty:0),CGAffineTransform(translationX:CGFloat.infinity,y:0)] {XCTAssertNil(EditedAvatarVideoGeometry(naturalSize:size,transform:t))}}
 func testInvalidNaturalSizeIsRejected() {for s in [CGSize.zero,CGSize(width:-1,height:20),CGSize(width:CGFloat.infinity,height:20),CGSize(width:CGFloat.nan,height:20)] {XCTAssertNil(EditedAvatarVideoGeometry(naturalSize:s,transform:.identity))}}
 func testSelectionMapsFromViewToVideoPixels() throws {let g=try XCTUnwrap(EditedAvatarVideoGeometry(naturalSize:size,transform:.identity)?.cropped(selection:CGRect(x:40,y:30,width:80,height:80),viewSize:CGSize(width:320,height:240)));XCTAssertEqual(g.size,CGSize(width:160,height:160));XCTAssertEqual(CGPoint(x:80,y:60).applying(g.transform),.zero);XCTAssertEqual(CGPoint(x:240,y:220).applying(g.transform),CGPoint(x:160,y:160))}
 func testRoundingRescalesEntireSelection() throws {let g=try XCTUnwrap(EditedAvatarVideoGeometry(naturalSize:size,transform:.identity)?.cropped(selection:CGRect(x:10,y:20,width:99,height:99),viewSize:size));XCTAssertEqual(g.size,CGSize(width:96,height:96));let far=CGPoint(x:109,y:119).applying(g.transform);XCTAssertEqual(far.x,96,accuracy:0.00001);XCTAssertEqual(far.y,96,accuracy:0.00001)}
 func testTinySelectionHasNonzeroEncoderDimensions() throws {let g=try XCTUnwrap(EditedAvatarVideoGeometry(naturalSize:size,transform:.identity)?.cropped(selection:CGRect(x:0,y:0,width:8,height:8),viewSize:size));XCTAssertEqual(g.size,CGSize(width:16,height:16));XCTAssertEqual(CGPoint(x:8,y:8).applying(g.transform),CGPoint(x:16,y:16))}
 func testPartiallyOutsideSelectionUsesVisibleRegion() throws {let g=try XCTUnwrap(EditedAvatarVideoGeometry(naturalSize:size,transform:.identity)?.cropped(selection:CGRect(x:-16,y:0,width:80,height:64),viewSize:size));XCTAssertEqual(g.size,CGSize(width:64,height:64));XCTAssertEqual(CGPoint.zero.applying(g.transform),.zero)}
 func testOutsideOrEmptySelectionIsRejected() throws {let g=try XCTUnwrap(EditedAvatarVideoGeometry(naturalSize:size,transform:.identity));for r in [CGRect.zero,CGRect(x:1000,y:0,width:10,height:10),CGRect(x:0,y:0,width:-1,height:10),CGRect(x:CGFloat.nan,y:0,width:10,height:10)] {XCTAssertNil(g.cropped(selection:r,viewSize:size))}}
 func testInvalidViewSizeIsRejectedBeforeDivision() throws {let g=try XCTUnwrap(EditedAvatarVideoGeometry(naturalSize:size,transform:.identity));for s in [CGSize.zero,CGSize(width:0,height:1),CGSize(width:CGFloat.infinity,height:1),CGSize(width:1,height:CGFloat.nan)] {XCTAssertNil(g.cropped(selection:CGRect(x:0,y:0,width:10,height:10),viewSize:s))}}
}
